const output = [];

for (const item of items) {
  const raw = item.json.body || item.json;
  const entries = Array.isArray(raw.entry) ? raw.entry : [];
  const changes = entries.flatMap((entry) => Array.isArray(entry.changes) ? entry.changes : []);
  const change = changes[0] || {};
  const value = change.value || raw.value || raw;

  const message = Array.isArray(value.messages) ? value.messages[0] : null;
  const contact = Array.isArray(value.contacts) ? value.contacts[0] : null;
  const status = Array.isArray(value.statuses) ? value.statuses[0] : null;

  const extractMessageText = (source) => {
    if (!source) return '';
    return (
      source.text?.body ||
      source.button?.text ||
      source.interactive?.button_reply?.title ||
      source.interactive?.list_reply?.title ||
      source.image?.caption ||
      source.video?.caption ||
      source.document?.caption ||
      source.caption ||
      source.conversation ||
      ''
    ).toString().trim();
  };

  const fallbackBody = raw.query || raw.body || raw;
  const fallbackMessage = (
    fallbackBody.chatInput ||
    fallbackBody.mensagem ||
    fallbackBody.message ||
    fallbackBody.text ||
    ''
  ).toString().trim();

  if (!message && !fallbackMessage) {
    output.push({
      json: {
        kind: status ? 'status' : 'ignored',
        id_candidato: '1313',
        eleitor_id: '',
        eleitor_uid: '',
        nome: '',
        telefone: '',
        email: '',
        cidade: '',
        bairro: '',
        mensagem_eleitor: '',
        tema_interesse: 'geral',
        intencao_voto: 'nao_classificada',
        sentimento: 'neutro',
        etapa_sugerida: 'novo_lead',
        score_delta: 0,
        consentimento_lgpd: true,
        canal_preferido: 'whatsapp',
        origem_captacao: 'datafy_chat',
        rotulo_ia: 'Resposta operacional de validacao da campanha.',
        mensagem_resposta: '',
        metadata: raw,
        status_event: status || null,
        response_message: status ? 'Evento de status recebido com sucesso.' : 'Evento recebido sem mensagem de eleitor.'
      }
    });
    continue;
  }

  const telefone = String(
    message?.from ||
    fallbackBody.telefone ||
    fallbackBody.phone ||
    ''
  ).replace(/\D/g, '');

  const email = (fallbackBody.email || '').toString().trim();
  const eleitorId = (
    fallbackBody.eleitor_id ||
    telefone ||
    email ||
    Date.now().toString()
  ).toString().trim();

  const mensagem = extractMessageText(message) || fallbackMessage;
  const nome = (
    contact?.profile?.name ||
    fallbackBody.senderName ||
    fallbackBody.nome ||
    fallbackBody.name ||
    'Eleitor'
  ).toString().trim();

  const mensagemLc = mensagem.toLowerCase();

  let tema = 'geral';
  if (mensagemLc.includes('educa')) tema = 'educacao';
  else if (mensagemLc.includes('saud')) tema = 'saude';
  else if (mensagemLc.includes('seguran')) tema = 'seguranca';
  else if (mensagemLc.includes('trabalho') || mensagemLc.includes('emprego')) tema = 'trabalho';
  else if (mensagemLc.includes('mobilidade') || mensagemLc.includes('transporte')) tema = 'mobilidade';

  let intencao = 'nao_classificada';
  if (mensagemLc.includes('apoio') || mensagemLc.includes('voto')) intencao = 'apoio';
  else if (mensagemLc.includes('duvida') || mensagemLc.includes('talvez')) intencao = 'indeciso';

  let sentimento = 'neutro';
  if (mensagemLc.includes('parab') || mensagemLc.includes('gostei') || mensagemLc.includes('apoio')) sentimento = 'positivo';
  else if (mensagemLc.includes('reclama') || mensagemLc.includes('ruim') || mensagemLc.includes('contra')) sentimento = 'negativo';

  let etapa = 'qualificado';
  if (intencao === 'apoio') etapa = 'engajado';
  if (!mensagem) etapa = 'novo_lead';

  const respostaBase = {
    educacao: 'Obrigado pela mensagem. O time do Eri Castro registrou seu interesse em educacao e retornara com conteudo qualificado.',
    saude: 'Obrigado pelo contato. O time do Eri Castro registrou seu interesse em saude para aprofundar esse tema com voce.',
    seguranca: 'Recebemos sua mensagem. O tema seguranca ja foi sinalizado para o relacionamento da campanha do Eri Castro.',
    trabalho: 'Obrigado pela mensagem. Registramos seu interesse em trabalho e desenvolvimento para a campanha do Eri Castro.',
    mobilidade: 'Recebemos sua mensagem. O tema mobilidade foi associado ao seu cadastro para continuidade do relacionamento.',
    geral: 'Obrigado pela mensagem. Seu contato foi registrado na campanha do Eri Castro e seguira para acompanhamento.'
  };

  output.push({
    json: {
      kind: 'inbound',
      id_candidato: '1313',
      eleitor_id: eleitorId,
      eleitor_uid: `1313:${eleitorId}`,
      nome,
      telefone,
      email,
      cidade: (fallbackBody.cidade || '').toString().trim(),
      bairro: (fallbackBody.bairro || '').toString().trim(),
      mensagem_eleitor: mensagem,
      tema_interesse: tema,
      intencao_voto: intencao,
      sentimento,
      etapa_sugerida: etapa,
      score_delta: intencao === 'apoio' ? 20 : 8,
      consentimento_lgpd: fallbackBody.consentimento_lgpd !== false,
      canal_preferido: 'whatsapp',
      origem_captacao: 'datafy_chat',
      rotulo_ia: 'Este atendimento e realizado por assistente virtual oficial da campanha.',
      mensagem_resposta: `Este atendimento e realizado por assistente virtual oficial da campanha.\n\n${respostaBase[tema]}`,
      metadata: raw,
      datafy_session_id: (fallbackBody.sessionId || '').toString(),
      datafy_connected_phone: (fallbackBody.connectedPhone || '').toString(),
      datafy_token: (fallbackBody.token || '').toString(),
      meta_phone_number_id: value.metadata?.phone_number_id || '',
      meta_display_phone_number: value.metadata?.display_phone_number || '',
      meta_message_id: message?.id || '',
      response_message: 'Mensagem inbound recebida e processada com sucesso.'
    }
  });
}

return output;

function pick(...values) {
  for (const value of values) {
    if (value === null || value === undefined) continue;
    const text = String(value).trim();
    if (text) return text;
  }
  return '';
}

function lower(value) {
  return String(value || '').toLowerCase();
}

function containsAny(text, terms) {
  return terms.some((term) => text.includes(term));
}

function extractProfileValue(markdown, label) {
  if (!markdown) return '';
  const regex = new RegExp('-\\s*' + label + ':\\s*(.*)', 'i');
  const match = String(markdown).match(regex);
  return match && match[1] ? match[1].trim() : '';
}

function formatDay(dateLike) {
  if (!dateLike) return '';
  const parsed = new Date(dateLike);
  if (Number.isNaN(parsed.getTime())) return '';
  return new Intl.DateTimeFormat('pt-BR', {
    timeZone: 'America/Sao_Paulo',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(parsed);
}

function isGenericName(name) {
  const value = lower(name);
  return !value || value === 'eleitor' || value === 'amigo' || value === 'contato';
}

return items.map((item) => {
  const text = pick(item.json.mensagem_eleitor);
  const textLc = lower(text);

  const nome = pick(item.json.ctx_nome, item.json.nome, '');
  const cidade = pick(item.json.ctx_cidade, item.json.cidade);
  const telefone = pick(item.json.ctx_telefone, item.json.telefone);
  const email = pick(item.json.ctx_email, item.json.email);
  const bairro = pick(item.json.ctx_bairro, item.json.bairro);

  const perfilMarkdown = pick(item.json.perfil_markdown);
  const ultimoTema = pick(item.json.ultimo_tema, item.json.ctx_tema_interesse);
  const ultimaMensagemEleitor = pick(item.json.ultima_mensagem_eleitor);
  const ultimaMensagemCampanha = pick(item.json.ultima_mensagem_campanha);
  const dataUltimoHistorico = pick(
    item.json.ultima_interacao_em,
    item.json.ctx_ultima_resposta_em,
    item.json.ctx_ultimo_contato_em
  );
  const etapaAnterior = pick(item.json.ctx_etapa_funil, item.json.etapa_sugerida, 'novo_lead');
  const intencaoAnterior = pick(item.json.ctx_intencao_voto, item.json.intencao_voto, 'nao_classificada');
  const scoreAnterior = Number(item.json.ctx_score_engajamento || 0);
  const eleitorConhecido = Boolean(item.json.ctx_eleitor_uid || item.json.ctx_nome || item.json.ctx_telefone);

  const hoje = formatDay(new Date());
  const ultimoHistoricoDia = formatDay(dataUltimoHistorico);
  const primeiraMensagemDoDia = !ultimoHistoricoDia || ultimoHistoricoDia !== hoje;

  const bandeiras = extractProfileValue(perfilMarkdown, 'bandeiras');
  const propostas = extractProfileValue(perfilMarkdown, 'propostas_top5');
  const porqueVotar = extractProfileValue(perfilMarkdown, 'porque_votar');

  const faltantes = [];
  if (isGenericName(nome)) faltantes.push('nome');
  if (!cidade) faltantes.push('cidade');
  if (!telefone) faltantes.push('telefone');
  const proximoDadoFaltante = faltantes[0] || '';

  const pedeApresentacao = containsAny(textLc, [
    'quem e ele',
    'quem é ele',
    'quem e eri castro',
    'quem e eri castro',
    'fala de eri castro',
    'me fala de eri castro',
    'quem e o candidato',
    'quem é o candidato',
  ]);

  const pedePartido = containsAny(textLc, [
    'qual e o partido',
    'qual é o partido',
    'partido dele',
    'partido do candidato',
    'de que partido',
    'sigla do partido',
  ]);

  const pedePropostas = containsAny(textLc, [
    'proposta',
    'propostas',
    'bandeira',
    'bandeiras',
    'plano',
    'planos',
  ]);

  const demonstraApoio = containsAny(textLc, [
    'vou votar',
    'meu voto',
    'apoio',
    'estou com ele',
    'quero ajudar',
    'quero participar',
    'top',
    'gostei',
    'bacana',
  ]);

  const querAgenda = containsAny(textLc, [
    'agenda',
    'evento',
    'reuniao',
    'reunião',
    'encontro',
  ]);

  let tema = item.json.tema_interesse || 'geral';
  if (pedePartido) tema = 'identidade_politica';
  else if (pedePropostas) tema = 'propostas';
  else if (querAgenda) tema = 'agenda';
  else if (pedeApresentacao) tema = 'apresentacao';
  else if (ultimoTema) tema = ultimoTema;

  let etapa = etapaAnterior || 'novo_lead';
  let intencao = intencaoAnterior || 'nao_classificada';
  let scoreDelta = 8;

  if (demonstraApoio) {
    etapa = 'engajado';
    intencao = 'apoio';
    scoreDelta = 18;
  } else if (eleitorConhecido && !faltantes.length) {
    etapa = etapaAnterior === 'novo_lead' ? 'qualificado' : etapaAnterior;
    scoreDelta = 10;
  } else if (faltantes.length) {
    etapa = 'qualificado';
    scoreDelta = 6;
  } else if (pedeApresentacao || pedePropostas || pedePartido || querAgenda) {
    etapa = 'relacionamento';
    scoreDelta = 12;
  }

  let sentimento = item.json.sentimento || 'neutro';
  if (demonstraApoio) sentimento = 'positivo';

  const nomeTratamento = isGenericName(nome) ? '' : nome;
  const resumoHistorico = [];

  if (eleitorConhecido) resumoHistorico.push('Eleitor conhecido na base. Nome salvo: ' + (nomeTratamento || 'não informado') + '.');
  else resumoHistorico.push('Eleitor ainda não reconhecido na base.');
  if (ultimoTema) resumoHistorico.push('Último tema tratado: ' + ultimoTema + '.');
  if (ultimaMensagemEleitor) resumoHistorico.push('Última mensagem do eleitor: ' + ultimaMensagemEleitor);
  if (ultimaMensagemCampanha) resumoHistorico.push('Última resposta enviada pela campanha: ' + ultimaMensagemCampanha);
  if (cidade) resumoHistorico.push('Cidade conhecida: ' + cidade + '.');
  if (telefone) resumoHistorico.push('Telefone conhecido: ' + telefone + '.');
  if (email) resumoHistorico.push('Email conhecido: ' + email + '.');
  if (bairro) resumoHistorico.push('Bairro conhecido: ' + bairro + '.');

  const resumoContextoIa = [
    'Primeira mensagem do dia: ' + (primeiraMensagemDoDia ? 'sim' : 'não'),
    'Nome disponível: ' + (nomeTratamento || 'não informado'),
    'Próximo dado faltante prioritário: ' + (proximoDadoFaltante || 'nenhum'),
    'Tema inferido nesta mensagem: ' + tema,
    'Etapa atual do funil sugerida: ' + etapa,
    'Intenção de voto inferida: ' + intencao,
    'Resumo do histórico: ' + (resumoHistorico.join(' ') || 'Sem histórico adicional.'),
    'Bandeiras registradas do candidato: ' + (bandeiras || 'não informado'),
    'Propostas registradas do candidato: ' + (propostas || 'não informado'),
    'Argumento institucional "por que votar": ' + (porqueVotar || 'não informado'),
  ].join('\n');

  return {
    json: {
      ...item.json,
      nome: nome || item.json.nome || 'Eleitor',
      cidade,
      bairro,
      telefone,
      email,
      tema_interesse: tema,
      etapa_sugerida: etapa,
      intencao_voto: intencao,
      sentimento,
      score_delta: scoreDelta,
      score_engajamento_contexto: scoreAnterior,
      eleitor_reconhecido: eleitorConhecido,
      primeira_mensagem_do_dia: primeiraMensagemDoDia,
      proximo_dado_faltante: proximoDadoFaltante,
      prompt_usuario_ia: text || '(sem texto)',
      resumo_contexto_ia: resumoContextoIa,
      chatInput: text || '(sem texto)',
      rotulo_ia: 'Resposta conversacional com contexto real do eleitor e do candidato no canal de teste Datafy.',
      mensagem_resposta: '',
      response_message: 'Contexto do inbound preparado para geração de resposta via IA.',
    },
  };
});

return items.map((item) => ({
  json: {
    status: 'ignored',
    message: item.json.response_message || 'Evento recebido sem mensagem de eleitor.',
    kind: item.json.kind || 'ignored',
    success: true
  }
}));

function pick(...values) {
  for (const value of values) {
    if (value === null || value === undefined) continue;
    const text = String(value).trim();
    if (text) return text;
  }
  return '';
}

return items.map((item) => {
  const mensagemResposta = pick(item.json.output, item.json.text, item.json.message, item.json.mensagem_resposta);
  return {
    json: {
      ...item.json,
      mensagem_resposta: mensagemResposta,
      output: mensagemResposta,
      text: mensagemResposta,
      message: mensagemResposta,
      response_message: 'Mensagem inbound recebida, enriquecida com contexto e respondida por IA com sucesso.',
      datafy_response: {
        success: true,
        status: 200,
        channel: 'datafy_chat',
        candidateId: item.json.id_candidato,
        electorId: item.json.eleitor_id,
        phone: item.json.telefone || '',
        replyText: mensagemResposta,
        reply: mensagemResposta,
        message: mensagemResposta,
        output: mensagemResposta,
      },
    },
  };
});
